using System.Text.Json;
using SilverModManager.Games.Bethesda.LoadOrder;
using SilverModManager.Games.Bethesda.Loot.Database;
using SilverModManager.Games.Bethesda.Loot.Masterlists;
using SilverModManager.Games.Bethesda.Loot.Sorting;
using SilverModManager.Games.Bethesda.Loot.Tests.Corpus;

namespace SilverModManager.Games.Bethesda.Loot.Tests.Sorting;

// Checks the sort against results libloot produced for the same synthetic plugins and metadata.
// The cases are generated by tools/loot-oracle/generate.py; this runs without Python.
public class CorpusTests
{
    private const string ExpectedLibLootVersion = "0.29.6";
    private const int Tier2Seeds = 40;
    private const int Tier3SeedsPerGame = 4;

    private static readonly string CorpusDirectory = Path.Combine(AppContext.BaseDirectory, "Corpus");

    public static TheoryData<string> CaseFiles()
    {
        var data = new TheoryData<string>();
        if (!Directory.Exists(CorpusDirectory)) return data;

        // The real load orders have their own test, which also times the sort and explains a mismatch.
        foreach (var file in Directory.EnumerateFiles(CorpusDirectory, "*.json", SearchOption.AllDirectories).Order(StringComparer.Ordinal))
        {
            if (file.StartsWith(RealCorpusTests.Directory, StringComparison.Ordinal)) continue;
            data.Add(Path.GetRelativePath(CorpusDirectory, file).Replace('\\', '/'));
        }

        return data;
    }

    [Fact]
    public void CorpusShouldHoldTheHandWrittenCasesEveryRandomSeedAndFourSeedsPerBundledMasterlist()
    {
        Directory.Exists(CorpusDirectory).Should().BeTrue("the generated corpus is copied next to the tests");

        Directory.EnumerateFiles(Path.Combine(CorpusDirectory, "tier1"), "*.json").Should().NotBeEmpty();
        Directory.EnumerateFiles(Path.Combine(CorpusDirectory, "tier2"), "*.json").Should().HaveCount(Tier2Seeds);

        var tier3 = Directory.EnumerateFiles(Path.Combine(CorpusDirectory, "tier3"), "*.json").Select(Path.GetFileName).ToList();
        tier3.Should().HaveCount(LootGameExtensions.BundledRepositories.Count * Tier3SeedsPerGame);
        foreach (var repo in LootGameExtensions.BundledRepositories)
            tier3.Should().Contain(Enumerable.Range(0, Tier3SeedsPerGame).Select(seed => $"{repo}_seed_{seed:000}.json"));
    }

    [Theory]
    [MemberData(nameof(CaseFiles))]
    public void ShouldSortTheWayLibLootDid(string file)
    {
        var corpusCase = CorpusCase.Load(Path.Combine(CorpusDirectory, file));
        corpusCase.LibLootVersion.Should().Be(ExpectedLibLootVersion);

        var game = CorpusGame.For(corpusCase.GameType);
        var plugins = corpusCase.Plugins.Select(p => game.ToSortingPlugin(p, corpusCase)).ToList();
        var database = corpusCase.BuildDatabase();

        if (corpusCase.Expected.Error is { } error)
        {
            var act = () => PluginSorter.Sort<ISortingPlugin>(plugins, database, game.EarlyLoaders);
            var thrown = act.Should().Throw<Exception>().Which;
            AssertSameError(error, thrown);
        }
        else
        {
            var result = PluginSorter.Sort<ISortingPlugin>(plugins, database, game.EarlyLoaders);
            result.Order.Should().Equal(corpusCase.Expected.Order!);

            // The tie-break edges join every pair of neighbours, so the order is the only valid one
            // (libloot's own tests assert this).
            result.UnlinkedNeighbours.Should().BeEmpty();

            if (corpusCase.Expected.Resorted is { } resorted)
            {
                resorted.Should().Equal(result.Order, "the oracle's second sort changed nothing");

                var byName = plugins.ToDictionary(p => p.Name, StringComparer.Ordinal);
                var second = PluginSorter.Sort<ISortingPlugin>(result.Order.Select(n => byName[n]).ToList(), database, game.EarlyLoaders);
                second.Order.Should().Equal(resorted);
            }
        }

        foreach (var expectedPath in corpusCase.GroupsPaths)
        {
            if (expectedPath.Error is { } pathError)
            {
                var act = () => database.GroupsPath(expectedPath.From, expectedPath.To);
                AssertSameError(pathError, act.Should().Throw<Exception>().Which);
            }
            else
            {
                database.GroupsPath(expectedPath.From, expectedPath.To)
                    .Select(v => (v.Name, v.OutEdgeType?.ToString()))
                    .Should().Equal(expectedPath.Path!.Select(v => (v.Name, v.EdgeType)),
                        $"the path from {expectedPath.From} to {expectedPath.To}");
            }
        }
    }

    private static void AssertSameError(OracleError expected, Exception actual)
    {
        switch (expected.Kind)
        {
            case "CyclicInteractionError":
                var cycle = FindCycle(actual);
                cycle.Should().NotBeNull($"libloot reported a cycle, but this threw {actual}");
                CyclicInteractionException.DisplayCycle(cycle!.Cycle).Should().Be(expected.CycleText);
                cycle.Cycle.Select(v => (v.Name, v.OutEdgeType?.ToString()))
                    .Should().Equal(expected.Cycle!.Select(v => (v.Name, v.EdgeType)));
                break;
            case "UndefinedGroupError":
                var group = actual switch
                {
                    UndefinedGroupException e => e.GroupName,
                    BuildGroupsGraphException { UndefinedGroup: { } e } => e.GroupName,
                    GroupsPathException { Kind: GroupsPathExceptionKind.UndefinedGroup } e => e.GroupName,
                    _ => null,
                };
                group.Should().NotBeNull($"libloot reported an undefined group, but this threw {actual}");
                expected.Message.Should().Contain($"\"{group}\"");
                break;
            default:
                throw new InvalidOperationException($"The corpus holds an oracle error this test does not map: {expected.Kind}: {expected.Message}");
        }
    }

    private static CyclicInteractionException? FindCycle(Exception exception) => exception switch
    {
        CyclicInteractionException e => e,
        PluginGraphValidationException e => e.Cycle,
        BuildGroupsGraphException e => e.Cycle,
        GroupsPathException { Kind: GroupsPathExceptionKind.CycleFound } e => e.InnerException as CyclicInteractionException,
        _ => null,
    };
}

internal sealed record OracleVertex(string Name, string? EdgeType)
{
    public static OracleVertex From(JsonElement element) =>
        new(element[0].GetString()!, element[1].ValueKind == JsonValueKind.Null ? null : element[1].GetString());
}

internal sealed record OracleError(string Kind, string Message, string? CycleText, IReadOnlyList<OracleVertex>? Cycle)
{
    public static OracleError From(JsonElement element) => new(
        element.GetProperty("kind").GetString()!,
        element.GetProperty("message").GetString()!,
        element.TryGetProperty("cycle_text", out var text) ? text.GetString() : null,
        element.TryGetProperty("cycle", out var cycle) ? cycle.EnumerateArray().Select(OracleVertex.From).ToList() : null);
}

internal sealed record OracleExpected(IReadOnlyList<string>? Order, IReadOnlyList<string>? Resorted, OracleError? Error);

internal sealed record OracleGroupsPath(string From, string To, IReadOnlyList<OracleVertex>? Path, OracleError? Error);

internal sealed record PluginSpec(string Name, uint Flags, IReadOnlyList<string> Masters);

/// <summary>One generated case: synthetic plugins and metadata in, libloot's answer out.</summary>
internal sealed record CorpusCase(
    string LibLootVersion,
    string GameType,
    PluginFormat Format,
    float HeaderVersion,
    IReadOnlyList<PluginSpec> Plugins,
    string? Masterlist,
    string? Userlist,
    string? Prelude,
    OracleExpected Expected,
    IReadOnlyList<OracleGroupsPath> GroupsPaths)
{
    public static CorpusCase Load(string path)
    {
        using var document = JsonDocument.Parse(System.IO.File.ReadAllText(path));
        var root = document.RootElement;

        string? Text(string name) => root.GetProperty(name).GetString();

        var expected = root.GetProperty("expected");
        var (masterlist, prelude) = root.TryGetProperty("real_masterlist", out var real)
            ? StrippedBundledText(real)
            : (Text("masterlist"), Text("prelude"));
        return new CorpusCase(
            Text("libloot_version")!,
            Text("game_type")!,
            Enum.Parse<PluginFormat>(Text("format")!),
            root.GetProperty("header_version").GetSingle(),
            root.GetProperty("plugins").EnumerateArray().Select(p => new PluginSpec(
                p.GetProperty("name").GetString()!,
                p.GetProperty("flags").GetUInt32(),
                p.GetProperty("masters").EnumerateArray().Select(m => m.GetString()!).ToList())).ToList(),
            masterlist,
            Text("userlist"),
            prelude,
            new OracleExpected(
                expected.TryGetProperty("order", out var order) ? order.EnumerateArray().Select(n => n.GetString()!).ToList() : null,
                expected.TryGetProperty("resorted", out var resorted) ? resorted.EnumerateArray().Select(n => n.GetString()!).ToList() : null,
                expected.TryGetProperty("error", out var error) ? OracleError.From(error) : null),
            root.GetProperty("groups_paths").EnumerateArray().Select(p => new OracleGroupsPath(
                p.GetProperty("from").GetString()!,
                p.GetProperty("to").GetString()!,
                p.TryGetProperty("path", out var path) ? path.EnumerateArray().Select(OracleVertex.From).ToList() : null,
                p.TryGetProperty("error", out var pathError) ? OracleError.From(pathError) : null)).ToList());
    }

    // Tier 3 stores hashes, not text. The bundled files are stripped here with the same code the
    // generator's input was stripped with, and must hash to what the oracle saw.
    private static (string Masterlist, string Prelude) StrippedBundledText(JsonElement real)
    {
        var repo = real.GetProperty("repository").GetString()!;
        var masterlist = StrippedMasterlists.Masterlist(repo);
        var prelude = StrippedMasterlists.Prelude();

        void Check(string what, string expected, string actual) =>
            actual.Should().Be(expected, $"the bundled {what} must be the one the oracle sorted with; regenerate the tier 3 corpus after refreshing the masterlists");

        Check($"{repo} masterlist", real.GetProperty("bundled_sha256").GetString()!, masterlist.BundledSha256);
        Check($"{repo} masterlist once stripped", real.GetProperty("stripped_sha256").GetString()!, masterlist.StrippedSha256);
        Check("prelude", real.GetProperty("prelude_bundled_sha256").GetString()!, prelude.BundledSha256);
        Check("prelude once stripped", real.GetProperty("prelude_stripped_sha256").GetString()!, prelude.StrippedSha256);
        return (masterlist.Stripped, prelude.Stripped);
    }

    public LootDatabase BuildDatabase()
    {
        var database = new LootDatabase();
        if (Masterlist is not null)
        {
            if (Prelude is not null) database.LoadMasterlistWithPrelude(Masterlist, Prelude);
            else database.LoadMasterlist(Masterlist);
        }

        if (Userlist is not null) database.LoadUserlist(Userlist);
        return database;
    }
}

/// <summary>What the corpus assumes about a game: header layout, flag rules and early loaders.</summary>
internal sealed record CorpusGame(bool MasterByExtension, bool SupportsLightPlugins, bool IsStarfield, IReadOnlyList<string> EarlyLoaders, bool MasterFlagIgnored = false)
{
    // The early loaders are libloadorder's hardcoded lists (game_settings.rs); the corpus has no
    // Creation Club list for them to grow by.
    private static readonly string[] SkyrimSEEarlyLoaders =
        ["Skyrim.esm", "Update.esm", "Dawnguard.esm", "HearthFires.esm", "Dragonborn.esm"];

    private static readonly string[] Fallout4EarlyLoaders =
    [
        "Fallout4.esm", "DLCRobot.esm", "DLCworkshop01.esm", "DLCCoast.esm", "DLCworkshop02.esm",
        "DLCworkshop03.esm", "DLCNukaWorld.esm", "DLCUltraHighResolution.esm",
    ];

    private static readonly string[] StarfieldEarlyLoaders =
    [
        "Starfield.esm", "Constellation.esm", "OldMars.esm", "ShatteredSpace.esm", "SFBGS003.esm", "SFBGS004.esm",
        "SFBGS006.esm", "SFBGS007.esm", "SFBGS008.esm", "SFBGS00D.esm", "SFBGS047.esm", "SFBGS050.esm",
    ];

    public static CorpusGame For(string gameType) => gameType switch
    {
        "SkyrimSE" => new CorpusGame(true, true, false, SkyrimSEEarlyLoaders),
        "Fallout4" => new CorpusGame(true, true, false, Fallout4EarlyLoaders),
        "Starfield" => new CorpusGame(true, true, true, StarfieldEarlyLoaders),
        "Skyrim" => new CorpusGame(true, false, false, ["Skyrim.esm"]),
        "Oblivion" or "Morrowind" or "Fallout3" or "FalloutNV" => new CorpusGame(false, false, false, []),
        // Oblivion Remastered ignores the master flag and the extension: libloot treats every plugin as a non-master.
        "OblivionRemastered" => new CorpusGame(false, false, false, [], MasterFlagIgnored: true),
        _ => throw new InvalidOperationException($"The corpus has no rules for the game {gameType}"),
    };

    public TestPlugin ToSortingPlugin(PluginSpec spec, CorpusCase corpusCase)
    {
        var header = new PluginHeader(spec.Name, spec.Masters, spec.Flags, corpusCase.HeaderVersion, 0, null, null, corpusCase.Format);
        var plugin = new TestPlugin(spec.Name)
        {
            IsMaster = PluginFlags.IsMaster(header, MasterByExtension, MasterFlagIgnored),
            IsBlueprintPlugin = PluginFlags.IsBlueprint(header, IsStarfield),
        };
        foreach (var master in spec.Masters) plugin.AddMaster(master);
        return plugin;
    }
}
